input.command:
cd /workspace
mkdir -p work
duckdb work/analysis.duckdb -c "
INSTALL spatial; INSTALL httpfs; LOAD spatial; LOAD httpfs;
CREATE OR REPLACE TABLE input_list AS
  SELECT cod_imovel, municipio AS list_municipio, cod_estado AS list_cod_estado
  FROM read_csv('lists/goias-sample.csv', header=true, encoding='utf-8');
SELECT count(*) FROM input_list;
SELECT count(distinct cod_imovel) FROM input_list;
"

cd /workspace
duckdb work/analysis.duckdb -c "
LOAD spatial; LOAD httpfs;
CREATE OR REPLACE TABLE car_matched AS
  SELECT c.*
  FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/Brazil_CAR_AREA_IMOVEL.parquet') c
  JOIN input_list l USING (cod_imovel);
SELECT count(*) n_rows, count(distinct cod_imovel) n_distinct FROM car_matched;
"

